type MyAction = { type: 'A' } | { type: 'B' }

function improved() {
  const m: Middleware<{}, any, Dispatch<MyAction>> = api => next => action => {
    // NEW: `action` should be the dispatch type's action type (MyAction)
    const typed: MyAction = action
    typed.type
    // @ts-expect-error - `nonexistent` is not on MyAction
    action.nonexistent
    return next(action)
  }
}

function defaulted() {
  const m: Middleware = api => next => action => {
    // Default: D = Dispatch => action is AnyAction (still assignable to AnyAction)
    const typed: AnyAction = action
    return next(action)
  }
