import {
  Middleware,
  MiddlewareAPI,
  applyMiddleware,
  createStore,
  Dispatch,
  Reducer,
  Action,
  StoreEnhancerStoreCreator,
  StoreEnhancer
} from 'redux'

type PromiseDispatch = <T extends Action>(promise: Promise<T>) => Promise<T>

function logger() {
  const m: Middleware = (api: MiddlewareAPI) => next => action => next(action)
  return m
}

function promise() {
  const m: Middleware<PromiseDispatch> = (api: MiddlewareAPI) => next => action =>
    next(action)
  return m
}

interface State {
  someField: 'string'
}
const reducer: Reducer<State> = null as any

// ---- Scenario A: how many middleware args does applyMiddleware accept? ----
const s0 = applyMiddleware()
const s1 = applyMiddleware(logger())
const s2 = applyMiddleware(logger(), logger())
const s3 = applyMiddleware(logger(), logger(), logger())
const s4 = applyMiddleware(logger(), logger(), logger(), logger())

// ---- Scenario B: calling the returned enhancer, then its store creator ----
const enh = applyMiddleware(logger())
const nextCreator: StoreEnhancerStoreCreator = createStore
const resultCreator = enh(nextCreator)
// store creator should only accept (reducer, preloadedState?)
resultCreator(reducer)
resultCreator(reducer, { someField: 'string' })
// @ts-expect-error store creator must NOT accept a third argument
resultCreator(reducer, { someField: 'string' }, 'extra')

// ---- Scenario C: what does the returned enhancer accept as its own param? ----
const fullStoreCreator = (
  reducer: any,
  preloadedState: any,
  enhancer: any
): any => {}
enh(fullStoreCreator)

// ---- Scenario D: direct use via createStore ----
createStore(reducer, applyMiddleware(promise()))
createStore(
  reducer,
  applyMiddleware(promise(), logger())
)
createStore(
  reducer,
  applyMiddleware(promise(), logger(), logger())
)

export {}

